const CACHE='tamatem-dina-prolog-v4-20261015-finale';
const CORE=['./','./index.html','./style.css','./app.js','./state.js','./channels.js','./data.js','./messages.js','./i18n.js','./manifest.webmanifest','./assets/icon.svg','./assets/workroom.png','./assets/characters.png','./assets/illness.png','./assets/threshold.png','./assets/river.png','./assets/garden-dry.png','./assets/garden-wet.png','./assets/chamber.png','./assets/morning.png'];
self.addEventListener('install',event=>event.waitUntil((async()=>{const cache=await caches.open(CACHE);await cache.addAll(CORE);await self.skipWaiting();})()));
self.addEventListener('activate',event=>event.waitUntil((async()=>{for(const key of await caches.keys())if(key.startsWith('tamatem-dina-prolog-')&&key!==CACHE)await caches.delete(key);await self.clients.claim();})()));
self.addEventListener('fetch',event=>{if(event.request.method!=='GET'||new URL(event.request.url).origin!==location.origin)return;const url=new URL(event.request.url);if(event.request.mode==='navigate'){event.respondWith((async()=>{try{const response=await fetch(event.request);if(response.ok)return response;}catch{}return await caches.match(new URL('./index.html',self.registration.scope).href)||Response.error();})());return;}event.respondWith((async()=>{const cache=await caches.open(CACHE);const hit=await cache.match(event.request,{ignoreSearch:true});return hit||fetch(event.request);})());});
self.addEventListener('message',event=>{if(event.data?.type!=='STATUS')return;event.waitUntil((async()=>{const cache=await caches.open(CACHE);const found=await Promise.all(CORE.map(url=>cache.match(new URL(url,self.registration.scope).href)));event.ports[0]?.postMessage({ready:found.every(Boolean)});})());});
